// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed params: caller address and nft address, and some other params to satisfy initialize signature
    function testFuzz_property(address caller, address nftAddress, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolen, bool payRoyalties) public {
        // Keep feeRate within allowed bounds (wide)
        feeRate = uint16(uint256(feeRate) % 6000); // still allows >5000 to be tested but we will assume <=5000 to reach initialized path
        vm.assume(feeRate <= 5000);

        // Prevent zero-address nftAddress? No need; nft may be zero in general. We want to detect when caller != nftAddress.

        // perform initialize as if called by 'caller'
        vm.prank(caller);
        // call initialize; it's non-payable so direct call
        bool ok;
        try c.initialize(address(0), nftAddress, vBase, vNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: when initialize succeeds, the nft getter equals the provided _nft argument.
        // We must assert a universal property: for any inputs where initialize returned successfully,
        // c.nft() == nftAddress. The mutant that sets nft = msg.sender will fail whenever caller != nftAddress and call succeeds.

        if (ok) {
            assertTrue(c.nft() == nftAddress);
        } else {
            // If initialize reverted, we cannot observe nft; still assert that ok is false OR property holds.
            // But specification requires exactly one assertTrue reading c. To satisfy that, we assert a property that
            // holds for all inputs on the correct contract: either initialize reverted, or nft equals provided.
            // However, the testing harness requires a single assertTrue; above branch already asserts when ok true.
            // For the ok false case we still need one assert; combine into single assert covering both cases.
            // To comply with the single-assert requirement, we restructure: do a single assertTrue below.
        }
    }
}

// Note: Due to the strict requirement of exactly one assert in the test function, we must provide a single assertion
// that covers both branches. However the harness above used conditional assert. To comply with the required file shape
// and single assertion, we replace the function with a corrected single-assert version below.

contract InvMutTest_Fix is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(address caller, address nftAddress, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolen, bool payRoyalties) public {
        feeRate = uint16(uint256(feeRate) % 6000);
        vm.assume(feeRate <= 5000);

        vm.prank(caller);
        bool ok;
        try c.initialize(address(0), nftAddress, vBase, vNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if initialize succeeded then nft() must equal the provided nftAddress
        // (this is the universal property the reference satisfies; the mutant fails when caller != nftAddress)
        assertTrue(!ok || c.nft() == nftAddress);
    }
}

