// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz the deciding parameters that initialize consumes
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // keep addresses wide but avoid the zero-address being used for the factory/immutable invariants (allowed here)
        // No tight assumptions so fuzzer can find a case that distinguishes mutant

        bool ok;
        // call initialize and capture whether it succeeded (reference: should succeed when not initialized)
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: on a fresh contract (initialized starts false) calling initialize should succeed (set initialized to true)
        // The mutant inverts the check and will cause this call to revert for some inputs (indeed for all inputs because initialized is false initially).
        assertTrue(ok);
    }
}
